private static long getMemNumFromRequestStr(String memStr) {
    int unitIndex = getMemUnitIndexFromRequestStr(memStr);
    String memNumStr = memStr.substring(0, unitIndex);
    return (long) Double.parseDouble(memNumStr);
}
